        const description = getDescriptionEditor()
        fireEvent.change(description, { target: { value: 'Shortcut body' } })
        fireEvent.keyDown(description, { ctrlKey: true, key: 'Enter' })

        await waitFor(() => expect(createCard).toHaveBeenCalledWith({
            body: 'Shortcut body',
