import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Stack,
    TextField,
    Tooltip,
    Typography,
    useMediaQuery,
    useTheme,
} from '@mui/material'
import Close from 'mdi-material-ui/Close'
import Plus from 'mdi-material-ui/Plus'
import type { ChangeEvent, FormEvent, KeyboardEvent } from 'react'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { CardDraft, CardTypeConfig, StateConfig } from '../../../data/data_types'
import { useCardCreationState } from '../../hooks/use_card_creation_state'
import type { MarkdownEditorHandle } from '../../editor/markdown_editor'
import { CardTypePillGroup } from './card_type_pill_group'
import { NewCardMarkdownEditor } from './new_card_markdown_editor'
import { NewCardColumnPicker } from './new_card_column_picker'

const DIALOG_WIDTH = 480
const DISCARD_CARD_MESSAGE = 'Discard this new card draft?'

interface NewCardDialogProps {
    cardBodyTemplate: string
    cardTypes: CardTypeConfig[]
    initialTargetStatus: string
    isLoading: boolean
    isProjectOpen: boolean
    open: boolean
    onClose: () => void
    onCreateCard: (draft: CardDraft, initialState: string) => Promise<void>
    states: StateConfig[]
}

/** Responsive form for creating a card in a selected board column. */
export function NewCardDialog(props: NewCardDialogProps) {
    const {
        cardBodyTemplate,
        cardTypes,
        initialTargetStatus,
        isLoading,
        isProjectOpen,
        onClose,
        onCreateCard,
        open,
        states,
    } = props
    const { isCreatingCard } = useCardCreationState()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const bodyEditorRef = useRef<MarkdownEditorHandle>(null)
    const wasOpenRef = useRef(false)
    const [isInsertedTemplateUntouched, setIsInsertedTemplateUntouched] = useState(false)
    const [targetStatus, setTargetStatus] = useState('')
    const [title, setTitle] = useState('')
    const [type, setType] = useState('')
    const defaultType = cardTypes[0]?.type ?? ''
    const defaultStatus = states[0]?.state ?? ''
    const selectedType = cardTypes.some((typeConfig) => typeConfig.type === type) ? type : defaultType
    const selectedStatus = states.some((stateConfig) => stateConfig.state === targetStatus) ? targetStatus : defaultStatus
    const isSubmitDisabled = !isProjectOpen || title.trim().length === 0
        || selectedType.length === 0 || selectedStatus.length === 0 || isLoading || isCreatingCard

    const resetForm = () => {
        bodyEditorRef.current?.setMarkdown('')
        setIsInsertedTemplateUntouched(false)
        setTargetStatus(initialTargetStatus)
        setTitle('')
        setType(defaultType)
    }

    useEffect(() => {
        if ((open && !wasOpenRef.current) || !isProjectOpen) {
            bodyEditorRef.current?.setMarkdown('')
            setIsInsertedTemplateUntouched(false)
            setTargetStatus(initialTargetStatus)
            setTitle('')
            setType(defaultType)
        }
        wasOpenRef.current = open && isProjectOpen
    }, [defaultType, initialTargetStatus, isProjectOpen, open])

    const closeDialog = () => {
        const body = bodyEditorRef.current?.getMarkdown() ?? ''
        const isDirty = title.length > 0
            || body.length > 0
            || selectedType !== defaultType
            || selectedStatus !== initialTargetStatus
        if (isDirty && !window.confirm(DISCARD_CARD_MESSAGE)) return

        resetForm()
        onClose()
    }

    const handleDialogClose = () => {
        closeDialog()
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitle(event.target.value)
    }

    const handleBodyDirtyChange = useCallback((dirty: boolean) => {
        if (dirty) setIsInsertedTemplateUntouched(false)
    }, [])

    const handleTemplateClick = () => {
        const body = bodyEditorRef.current?.getMarkdown() ?? ''
        if (isInsertedTemplateUntouched && body === cardBodyTemplate) {
            bodyEditorRef.current?.setMarkdown('')
            setIsInsertedTemplateUntouched(false)

            return
        }

        const nextBody = body.length > 0 ? `${body}\n\n${cardBodyTemplate}` : cardBodyTemplate
        bodyEditorRef.current?.setMarkdown(nextBody)
        setIsInsertedTemplateUntouched(body.length === 0)
    }

    const handleCreateClick = async () => {
        if (isSubmitDisabled) return

        const body = bodyEditorRef.current?.getMarkdown() ?? ''
        const draft: CardDraft = {
            body,
            bodyIncludesTemplate: true,
            title: title.trim(),
            type: selectedType,
        }
        try {
            await onCreateCard(draft, selectedStatus)
        } catch {
            return
        }
        resetForm()
    }

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault()
        await handleCreateClick()
    }

    const handleFormKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
        if (event.key === 'Escape') {
            event.preventDefault()
            closeDialog()

            return
        }

        if (event.key !== 'Enter' || !event.ctrlKey) return

        event.preventDefault()
        void handleCreateClick()
    }

    const templateButtonLabel = isInsertedTemplateUntouched ? 'Clear' : 'Template'
    const createButton = (
        <Button aria-label="Create card" disabled={isSubmitDisabled} type="submit" variant="contained">
            <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                <Plus sx={{ fontSize: 17 }} />
                <span>Add</span>
                {!isMobile ? (
                    <Box
                        component="span"
                        sx={{
                            bgcolor: 'rgba(255,255,255,0.18)',
                            borderRadius: '5px',
                            fontSize: 10.5,
                            fontWeight: 600,
                            px: 0.625,
                            py: 0.25,
                        }}
                    >
                        Ctrl+â†µ
                    </Box>
                ) : null}
            </Stack>
        </Button>
    )

    return (
        <Dialog
            aria-labelledby="new-card-dialog-heading"
            fullScreen={isMobile}
            maxWidth={false}
            onClose={handleDialogClose}
            open={open}
            slotProps={{
                backdrop: { sx: { backdropFilter: 'blur(2px)', backgroundColor: 'rgba(16, 24, 40, 0.45)' } },
                paper: {
                    sx: {
                        border: isMobile ? 0 : 1,
                        borderColor: 'divider',
                        borderRadius: isMobile ? 0 : '14px',
                        boxShadow: isMobile ? 'none' : '0 24px 60px rgba(16,24,40,0.28)',
                        height: isMobile ? '100dvh' : 'auto',
                        maxHeight: isMobile ? '100dvh' : 'calc(100dvh - 32px)',
                        maxWidth: isMobile ? '100%' : 'calc(100% - 32px)',
                        overflow: 'hidden',
                        width: isMobile ? '100%' : DIALOG_WIDTH,
                    },
                },
            }}
        >
            <Box
                component="form"
                onKeyDown={handleFormKeyDown}
                onSubmit={handleSubmit}
                sx={{ display: 'flex', flexDirection: 'column', height: isMobile ? '100%' : 'auto', maxHeight: '100dvh', minHeight: 0 }}
            >
                <DialogTitle
                    component="div"
                    id="new-card-dialog-header"
                    sx={{
                        alignItems: 'center',
                        borderBottom: 1,
                        borderColor: 'divider',
                        display: 'flex',
                        flexShrink: 0,
                        gap: 1.25,
                        minHeight: isMobile ? 56 : 62,
                        px: isMobile ? 1 : 2.25,
                        py: 1,
                    }}
                >
                    {isMobile ? (
                        <Button onClick={closeDialog} sx={{ minHeight: 44, minWidth: 72 }} type="button" variant="text">
                            Cancel
                        </Button>
                    ) : (
                        <Box
                            sx={{
                                alignItems: 'center',
                                bgcolor: 'custom.primaryBg',
                                borderRadius: 1,
                                color: 'primary.main',
                                display: 'flex',
                                height: 30,
                                justifyContent: 'center',
                                width: 30,
                            }}
                        >
                            <Plus sx={{ fontSize: 18 }} />
                        </Box>
                    )}
                    <Typography
                        component="h2"
                        id="new-card-dialog-heading"
                        sx={{
                            flex: 1,
                            fontSize: isMobile ? 16 : 15.5,
                            fontWeight: 700,
                            textAlign: isMobile ? 'center' : 'left',
                        }}
                    >
                        New card
                    </Typography>
                    {isMobile ? (
                        <Button disabled={isSubmitDisabled} sx={{ minHeight: 44, minWidth: 72 }} type="submit" variant="text">
                            Create
                        </Button>
                    ) : (
                        <Tooltip title="Close">
                            <IconButton aria-label="Close" onClick={closeDialog} size="small" sx={{ height: 30, width: 30 }}>
                                <Close sx={{ fontSize: 17 }} />
                            </IconButton>
                        </Tooltip>
                    )}
                </DialogTitle>
                <DialogContent
                    data-testid="new-card-dialog-content"
                    sx={{
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'column',
                        gap: isMobile ? 2.25 : 2,
                        minHeight: 0,
                        overflowY: 'auto',
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 2.25 : 2.25,
                    }}
                >
                    <TextField
                        autoFocus
                        fullWidth
                        id="new-card-title"
                        onChange={handleTitleChange}
                        placeholder="Card titleâ€¦"
                        slotProps={{ htmlInput: { 'aria-label': 'Title' } }}
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                borderRadius: isMobile ? '11px' : '9px',
                                mt: 1,
                                height: isMobile ? 48 : 46,
                                '&.Mui-focused': { boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}` },
                                '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderWidth: 1 },
                                '& .MuiOutlinedInput-notchedOutline': { borderColor: 'custom.borderStrong' },
                            },
                            '& input': {
                                fontSize: isMobile ? 18 : 17,
                                fontWeight: 600,
                            },
                        }}
                        value={title}
                        variant="outlined"
                    />
                    <CardTypePillGroup
                        cardTypes={cardTypes}
                        isMobile={isMobile}
                        onChange={setType}
                        selectedType={selectedType}
                    />
                    <Stack spacing={isMobile ? 1.125 : 0.875}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <Typography color="text.secondary" id="new-card-description-label" sx={{ fontSize: 12, fontWeight: 600 }}>
                                Description
                            </Typography>
                            {!isMobile ? (
                                <Typography color="custom.text3" sx={{ fontSize: 11.5 }}>
                                    Markdown
                                </Typography>
                            ) : null}
                            <Box sx={{ flex: 1 }} />
                            <Button
                                disabled={cardBodyTemplate.length === 0}
                                onClick={handleTemplateClick}
                                size="small"
                                sx={{ minHeight: isMobile ? 44 : 30 }}
                                type="button"
                                variant="outlined"
                            >
                                {templateButtonLabel}
                            </Button>
                        </Stack>
                        <Box
                            aria-labelledby="new-card-description-label"
                            data-testid="new-card-description"
                            role="group"
                            sx={{
                                bgcolor: 'background.paper',
                                border: 1,
                                borderColor: 'custom.borderStrong',
                                borderRadius: isMobile ? '11px' : '9px',
                                boxSizing: 'border-box',
                                color: 'text.primary',
                                height: isMobile ? 260 : 270,
                                minHeight: isMobile ? 260 : 270,
                                outline: 'none',
                                overflow: 'auto',
                                resize: isMobile ? 'none' : 'vertical',
                                width: '100%',
                                '&:focus-within': {
                                    borderColor: 'primary.main',
                                    boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}`,
                                },
                                '&:hover:not(:focus-within)': { borderColor: 'custom.borderHover' },
                                '& > [data-sticky-toolbar]': { minHeight: '100%' },
                                '& .light-theme, & .dark-theme': { minHeight: '100%' },
                                '& .mdxeditor-content': {
                                    boxSizing: 'border-box',
                                    minHeight: isMobile ? 258 : 268,
                                    p: 1.625,
                                },
                            }}
                        >
                            <NewCardMarkdownEditor
                                onDirtyChange={handleBodyDirtyChange}
                                ref={bodyEditorRef}
                            />
                        </Box>
                    </Stack>
                </DialogContent>
                <DialogActions
                    sx={{
                        alignItems: 'stretch',
                        bgcolor: 'background.default',
                        borderTop: 1,
                        borderColor: 'divider',
                        flexDirection: isMobile ? 'column' : 'row',
                        flexShrink: 0,
                        gap: isMobile ? 1.5 : 1,
                        justifyContent: 'space-between',
                        m: 0,
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 1.5 : 1.5,
                        pb: isMobile ? 'max(12px, env(safe-area-inset-bottom))' : 1.5,
                    }}
                >
                    <NewCardColumnPicker
                        isMobile={isMobile}
                        onChange={setTargetStatus}
                        selectedStatus={selectedStatus}
                        states={states}
                    />
                    {isMobile ? createButton : (
                        <Stack direction="row" spacing={1}>
                            <Button onClick={closeDialog} type="button" variant="outlined">
                                Cancel
                            </Button>
                            {createButton}
                        </Stack>
                    )}
                </DialogActions>
            </Box>
        </Dialog>
    )
}

import { memo, forwardRef } from 'react'
import { MarkdownEditor, type MarkdownEditorHandle } from '../../editor/markdown_editor'

interface NewCardMarkdownEditorProps {
    onDirtyChange: (dirty: boolean) => void
}

const handleChange = () => undefined

/** Lifetime-stable Markdown editor boundary for a new-card draft. */
export const NewCardMarkdownEditor = memo(forwardRef<MarkdownEditorHandle, NewCardMarkdownEditorProps>(
    function NewCardMarkdownEditor(props, ref) {
        const { onDirtyChange } = props

        return (
            <MarkdownEditor
                hideToolbar
                markdown=""
                onChange={handleChange}
                onDirtyChange={onDirtyChange}
                ref={ref}
            />
        )
    },
))

import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_STATES,
    type BranchReference,
    type ProjectReference,
    type RepositoryReference,
} from '../../../data/data_types'
import {
    configureRemoteControlConnection,
    REMOTE_CONTROL_ENDPOINT_KEY,
} from '../../../data/remote_control_connection'
import { AppThemeProvider } from '../../../theme/theme_provider'
import { BranchSwitchDialog } from './branch_switch_dialog'
import { CompleteReleaseDialog } from './complete_release_dialog'
import { NewCardDialog } from './new_card_dialog'
import { ProjectOpenDialog } from './project_open_dialog'
import { WorkingFolderChooserDialog } from './working_folder_chooser_dialog'

const BRANCHES: BranchReference[] = [{ name: 'main' }]
const PROJECT: ProjectReference = { branch: 'main', id: 'local', rootPath: 'C:/repo' }
const REPOSITORIES: RepositoryReference[] = [{ branch: 'main', id: 'octo/demo', owner: 'octo', repository: 'demo' }]

function mockMatchMedia(matches: boolean) {
    window.matchMedia = ((query: string) => ({
        addEventListener: () => {},
        addListener: () => {},
        dispatchEvent: () => false,
        matches,
        media: query,
        onchange: null,
        removeEventListener: () => {},
        removeListener: () => {},
    })) as unknown as typeof window.matchMedia
}

function getDescriptionEditor() {
    return within(screen.getByRole('group', { name: 'Description' })).getByRole('textbox')
}

describe('project dialog components', () => {
    beforeEach(() => {
        mockMatchMedia(false)
    })

    afterEach(() => {
        cleanup()
        vi.restoreAllMocks()
        window.localStorage.removeItem(REMOTE_CONTROL_ENDPOINT_KEY)
    })

    it('renders the open project dialog without mounting the menu', () => {
        render(
            <ProjectOpenDialog
                branches={BRANCHES}
                isDesktopMode={false}
                isGithubAuthenticated
                isLoading={false}
                projectOpenResolution={null}
                onBranchChange={vi.fn()}
                onClose={vi.fn()}
                onCreateProjectFolders={vi.fn()}
                onCreateRemoteProject={vi.fn((rootPath, branch) => ({ branch, id: rootPath, rootPath }))}
                onCreateWorkingFolder={vi.fn()}
                onDiscardGithubPendingCommits={vi.fn()}
                onLoadManualBranches={vi.fn(async () => ({ branches: BRANCHES, repository: REPOSITORIES[0] }))}
                onLoadRemoteBranches={vi.fn(async () => BRANCHES)}
                onOpenGithub={vi.fn()}
                onOpenRemote={vi.fn()}
                onRepositoryChange={vi.fn(async () => BRANCHES)}
                onSourceChange={vi.fn()}
                onUseWorkingFolder={vi.fn()}
                open
                pendingGithubConflictProject={null}
                repositories={REPOSITORIES}
            />,
        )

        expect(screen.getByRole('dialog', { name: 'Open project' })).toBeInTheDocument()
        expect(screen.getByLabelText('Filter repositories')).toBeInTheDocument()
    })

    it('keeps branch entry editable when no branch options exist', () => {
        const openGithub = vi.fn()

        render(
            <ProjectOpenDialog
                branches={[]}
                isDesktopMode={false}
                isGithubAuthenticated
                isLoading={false}
                projectOpenResolution={null}
                onBranchChange={vi.fn()}
                onClose={vi.fn()}
                onCreateProjectFolders={vi.fn()}
                onCreateRemoteProject={vi.fn((rootPath, branch) => ({ branch, id: rootPath, rootPath }))}
                onCreateWorkingFolder={vi.fn()}
                onDiscardGithubPendingCommits={vi.fn()}
                onLoadManualBranches={vi.fn(async () => ({ branches: BRANCHES, repository: REPOSITORIES[0] }))}
                onLoadRemoteBranches={vi.fn(async () => BRANCHES)}
                onOpenGithub={openGithub}
                onOpenRemote={vi.fn()}
                onRepositoryChange={vi.fn(async () => BRANCHES)}
                onSourceChange={vi.fn()}
                onUseWorkingFolder={vi.fn()}
                open
                pendingGithubConflictProject={null}
                repositories={[]}
            />,
        )

        fireEvent.change(screen.getByLabelText('Owner'), { target: { value: 'octo' } })
        fireEvent.change(screen.getByRole('textbox', { name: 'Repository' }), { target: { value: 'demo' } })
        fireEvent.change(screen.getByLabelText('Branch'), { target: { value: 'topic' } })
        fireEvent.click(screen.getByRole('button', { name: 'Open GitHub' }))

        expect(openGithub).toHaveBeenCalledWith('octo', 'demo', 'topic')
    })

    it('preselects the remote source and prefills the stored connection settings', () => {
        configureRemoteControlConnection({ endpoint: 'ws://192.168.0.10:1234' })

        render(
            <ProjectOpenDialog
                branches={[]}
                initialSource="remote"
                isDesktopMode={false}
                isGithubAuthenticated={false}
                isLoading={false}
                projectOpenResolution={null}
                onBranchChange={vi.fn()}
                onClose={vi.fn()}
                onCreateProjectFolders={vi.fn()}
                onCreateRemoteProject={vi.fn((rootPath, branch) => ({ branch, id: rootPath, rootPath }))}
                onCreateWorkingFolder={vi.fn()}
                onDiscardGithubPendingCommits={vi.fn()}
                onLoadManualBranches={vi.fn(async () => ({ branches: BRANCHES, repository: REPOSITORIES[0] }))}
                onLoadRemoteBranches={vi.fn(async () => BRANCHES)}
                onOpenGithub={vi.fn()}
