            const nextMarkdown = getTestLexicalText()
            if (nextMarkdown === currentMarkdown) return
            latestMarkdownRef.current = nextMarkdown
            setRenderedMarkdown(nextMarkdown)
            onChange?.(nextMarkdown)
        }

